import io
import pandas as pd


def load(text):
    return pd.read_csv(io.StringIO(text), dtype={"receipt": str})


def profile(df):
    return {
        "rows": len(df),
        "missing": {col: int(n) for col, n in df.isna().sum().items() if n > 0},
        "items": int(df["item"].nunique()),
    }


def revenue_by_item(df):
    clean = df.dropna(subset=["qty", "price"])
    revenue = clean["qty"] * clean["price"]
    return {item: round(float(revenue[clean["item"] == item].sum()), 2) for item in clean["item"].unique()}
